func TestPostgresReadOnlyPagingAndCancellation(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	manager := New(nil)
	defer manager.Close()
	config := integrationConnection(t)
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Skipf("Qurio integration PostgreSQL is not running: %v", err)
	}
	result, err := manager.Execute(ctx, config.ID, "SELECT i, '행-' || i::text AS label FROM generate_series(1,5) AS t(i) ORDER BY i", 2, 2)
	if err != nil {
		t.Fatal(err)
	}
	if result.RowCount != 2 || !result.HasNext || len(result.Columns) != 2 || result.Rows[0][1] != "행-3" {
		t.Fatalf("unexpected page: %#v", result)
	}
	if _, err := manager.Execute(ctx, config.ID, "DELETE FROM users", 1, 10); err == nil {
		t.Fatal("mutation reached database")
	}
	operatorResult, err := manager.Execute(ctx, config.ID, `SELECT '{"allowed":true}'::jsonb @> '{"allowed":true}'::jsonb AS contained`, 1, 1)
	if err != nil || operatorResult.RowCount != 1 {
		t.Fatalf("PostgreSQL @> operator was affected by Oracle DB-link policy: result=%+v error=%v", operatorResult, err)
	}
	if _, err := manager.Execute(ctx, config.ID,
		`WITH recent(id) AS NOT MATERIALIZED (SELECT id FROM public.users) SELECT id FROM recent ORDER BY id`, 1, 1); err != nil {
		t.Fatalf("CTE column list/materialization grammar was rejected: %v", err)
	}
	config.Timeout = 100 * time.Millisecond
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatal(err)
	}
	started := time.Now()
	if _, err := manager.Execute(ctx, config.ID, "SELECT pg_sleep(5)", 1, 1); err == nil {
		t.Fatal("timed query unexpectedly succeeded")
	}
	if elapsed := time.Since(started); elapsed > time.Second {
		t.Fatalf("query cancellation took %s", elapsed)
	}
}

func TestPostgresLiveValidationAndSchemaExploration(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	manager := New(nil)
	defer manager.Close()
	config := integrationConnection(t)
	config.AllowedSchemas = []string{"public"}
	config.MaxRows = 2
	snapshot, err := manager.Upsert(ctx, config)
	if err != nil {
		t.Skipf("Qurio integration PostgreSQL is not running: %v", err)
	}
	if snapshot.MaxRows != 2 || len(snapshot.AllowedSchemas) != 1 || snapshot.AllowedSchemas[0] != "public" {
		t.Fatalf("profile policy snapshot = %+v", snapshot)
	}
	if _, err := manager.Execute(ctx, config.ID, "SELECT generate_series(1, 3)", 1, 3); !errors.Is(err, ErrRowLimitExceeded) {
		t.Fatalf("row-limit error = %v", err)
	}
	bounded, err := manager.Execute(ctx, config.ID, "SELECT generate_series(1, 3)", 1, 0)
	if err != nil || bounded.RowCount != 2 || bounded.Limit != 2 || !bounded.HasNext {
		t.Fatalf("policy-bounded execution = %+v, %v", bounded, err)
	}
	if _, err := manager.Execute(ctx, config.ID, "SELECT * FROM information_schema.tables", 1, 1); !errors.Is(err, ErrSchemaNotAllowed) {
		t.Fatalf("schema-policy execution error = %v", err)
	}
	rejected, err := manager.Validate(ctx, config.ID, "SELECT * FROM information_schema.tables")
	var schemaError *ValidationError
	if !errors.As(err, &schemaError) || !errors.Is(err, ErrSchemaNotAllowed) || rejected.Diagnostic == nil || rejected.Diagnostic.Code != "schema_not_allowed" {
		t.Fatalf("schema-policy validation = %+v, %T %v", rejected, err, err)
	}
	validation, err := manager.Validate(ctx, config.ID, "SELECT id FROM public.users LIMIT 1")
	if err != nil || !validation.Valid || validation.Strategy != "read_only_explain" {
		t.Fatalf("validation=%+v error=%v", validation, err)
	}
	invalid, err := manager.Validate(ctx, config.ID, "SELECT qurio_missing_column FROM public.users")
	var validationError *ValidationError
	if !errors.As(err, &validationError) || invalid.Valid || validationError.Diagnostic.Code != "42703" {
		t.Fatalf("invalid=%+v error=%T %v", invalid, err, err)
	}
	schema, err := manager.ExploreSchema(ctx, config.ID, 5000)
	if err != nil {
		t.Fatal(err)
	}
	foundUsers := false
	for _, table := range schema.Tables {
		if table.Schema != "public" {
			t.Fatalf("disallowed schema leaked into exploration: %+v", table)
		}
		if table.Schema == "public" && table.Name == "users" {
			foundUsers = true
			break
		}
	}
	if !foundUsers {
		t.Fatalf("public.users not found in %d live tables", len(schema.Tables))
	}
	for _, foreignKey := range schema.ForeignKeys {
		if foreignKey.Schema != "public" || foreignKey.ReferenceSchema != "public" {
			t.Fatalf("disallowed foreign key leaked into exploration: %+v", foreignKey)
		}
	}
}

func TestPostgresTargetedSchemaExplorationFindsPostPrefixPKAndFK(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	config := integrationConnection(t)
	config.AllowedSchemas = []string{"public"}
	setup, err := open(config)
	if err != nil {
		t.Skipf("Qurio integration PostgreSQL is not running: %v", err)
	}
	defer setup.Close()
	for _, statement := range []string{
		`DROP TABLE IF EXISTS public.zzzz_qurio_targeted_child`,
		`DROP TABLE IF EXISTS public.zzzz_qurio_targeted_parent`,
		`CREATE TABLE public.zzzz_qurio_targeted_parent(id bigint PRIMARY KEY)`,
		`CREATE TABLE public.zzzz_qurio_targeted_child(id bigint PRIMARY KEY,parent_id bigint NOT NULL REFERENCES public.zzzz_qurio_targeted_parent(id))`,
	} {
		if _, err := setup.ExecContext(ctx, statement); err != nil {
			t.Fatalf("prepare targeted schema fixture: %v", err)
		}
	}
	defer func() {
		_, _ = setup.ExecContext(context.Background(), `DROP TABLE IF EXISTS public.zzzz_qurio_targeted_child`)
		_, _ = setup.ExecContext(context.Background(), `DROP TABLE IF EXISTS public.zzzz_qurio_targeted_parent`)
	}()

	manager := New(nil)
	defer manager.Close()
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatal(err)
	}
	broad, err := manager.ExploreSchema(ctx, config.ID, 1)
	if err != nil || !broad.Truncated {
		t.Fatalf("one-column broad snapshot = %+v, %v", broad, err)
	}
	for _, table := range broad.Tables {
		if table.Name == "zzzz_qurio_targeted_child" {
			t.Fatalf("fixture unexpectedly appeared in alphabetical prefix: %+v", broad)
		}
	}

	targeted, err := manager.ExploreSchemaTargets(ctx, config.ID, []SchemaTarget{{Schema: "public", Table: "zzzz_qurio_targeted_child"}}, 20)
	if err != nil || targeted.Truncated || len(targeted.Tables) != 1 || targeted.Tables[0].Name != "zzzz_qurio_targeted_child" || len(targeted.Tables[0].Columns) != 2 {
		t.Fatalf("targeted snapshot = %+v, %v", targeted, err)
	}
	primaryKey := false
	for _, column := range targeted.Tables[0].Columns {
		if column.Name == "id" && column.PrimaryKey {
			primaryKey = true
		}
	}
	if !primaryKey {
		t.Fatalf("targeted primary key missing: %+v", targeted.Tables[0])
	}
	if len(targeted.ForeignKeys) != 1 || targeted.ForeignKeys[0].Table != "zzzz_qurio_targeted_child" || targeted.ForeignKeys[0].ReferenceTable != "zzzz_qurio_targeted_parent" {
		t.Fatalf("targeted foreign key missing: %+v", targeted.ForeignKeys)
	}

	missing, err := manager.ExploreSchemaTargets(ctx, config.ID, []SchemaTarget{{Schema: "public", Table: "qurio_target_does_not_exist"}}, 20)
	if err != nil || len(missing.Tables) != 0 || len(missing.ForeignKeys) != 0 {
		t.Fatalf("missing target snapshot = %+v, %v", missing, err)
	}
}

func TestPostgresRejectsImplicitUserCodeDispatch(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	config := integrationConnection(t)
	config.AllowedSchemas = []string{"public"}
	setup, err := open(config)
	if err != nil {
		t.Skipf("Qurio integration PostgreSQL is not running: %v", err)
	}
	defer setup.Close()
	statements := []string{
		`DROP TABLE IF EXISTS public.qurio_policy_partition_opclass CASCADE`,
		`DROP TABLE IF EXISTS public.qurio_policy_partition_expression CASCADE`,
		`DROP OPERATOR CLASS IF EXISTS public.qurio_policy_partition_ops USING btree`,
		`DROP FUNCTION IF EXISTS public.qurio_policy_partition_key(integer)`,
		`CREATE TABLE IF NOT EXISTS public.qurio_policy_probe(id integer)`,
		`CREATE OR REPLACE FUNCTION public.qurio_policy_effect(integer,integer) RETURNS integer LANGUAGE plpgsql VOLATILE AS $$ BEGIN PERFORM pg_notify('qurio_policy_probe',$1::text); RETURN $1+$2; END $$`,
		`DROP OPERATOR IF EXISTS public.## (integer,integer)`,
		`CREATE OPERATOR public.## (LEFTARG=integer,RIGHTARG=integer,FUNCTION=public.qurio_policy_effect)`,
		`CREATE OR REPLACE FUNCTION public.qurio_policy_constraint(integer) RETURNS boolean LANGUAGE plpgsql VOLATILE AS $$ BEGIN PERFORM pg_notify('qurio_policy_probe',$1::text); RETURN true; END $$`,
		`DROP DOMAIN IF EXISTS public.qurio_policy_domain CASCADE`,
		`CREATE DOMAIN public.qurio_policy_domain AS integer CHECK (public.qurio_policy_constraint(VALUE))`,
		`CREATE TABLE public.qurio_policy_domain_table(value public.qurio_policy_domain)`,
		`CREATE OR REPLACE VIEW public.qurio_policy_inner_view AS SELECT public.qurio_policy_effect(id,1) AS value FROM public.qurio_policy_probe`,
		`CREATE OR REPLACE VIEW public.qurio_policy_view AS SELECT value FROM public.qurio_policy_inner_view`,
		`CREATE OR REPLACE FUNCTION public.qurio_policy_partition_key(integer) RETURNS integer LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN PERFORM pg_notify('qurio_policy_probe',$1::text); RETURN $1; END $$`,
		`CREATE TABLE public.qurio_policy_partition_expression(id integer) PARTITION BY RANGE (public.qurio_policy_partition_key(id))`,
		`CREATE OPERATOR CLASS public.qurio_policy_partition_ops FOR TYPE integer USING btree AS OPERATOR 1 <, OPERATOR 2 <=, OPERATOR 3 =, OPERATOR 4 >=, OPERATOR 5 >, FUNCTION 1 btint4cmp(integer,integer)`,
		`CREATE TABLE public.qurio_policy_partition_opclass(id integer) PARTITION BY RANGE (id public.qurio_policy_partition_ops)`,
	}
	for _, statement := range statements {
		if _, err := setup.ExecContext(ctx, statement); err != nil {
			t.Fatalf("prepare policy probe: %v", err)
		}
	}
	defer func() {
		for _, statement := range []string{
			`DROP TABLE IF EXISTS public.qurio_policy_partition_opclass CASCADE`,
			`DROP TABLE IF EXISTS public.qurio_policy_partition_expression CASCADE`,
			`DROP OPERATOR CLASS IF EXISTS public.qurio_policy_partition_ops USING btree`,
			`DROP FUNCTION IF EXISTS public.qurio_policy_partition_key(integer)`,
			`DROP VIEW IF EXISTS public.qurio_policy_view`,
			`DROP VIEW IF EXISTS public.qurio_policy_inner_view`,
			`DROP TABLE IF EXISTS public.qurio_policy_domain_table`,
			`DROP DOMAIN IF EXISTS public.qurio_policy_domain`,
			`DROP OPERATOR IF EXISTS public.## (integer,integer)`,
			`DROP FUNCTION IF EXISTS public.qurio_policy_constraint(integer)`,
			`DROP FUNCTION IF EXISTS public.qurio_policy_effect(integer,integer)`,
			`DROP TABLE IF EXISTS public.qurio_policy_probe`,
		} {
			_, _ = setup.ExecContext(context.Background(), statement)
		}
	}()

	manager := New(nil)
	defer manager.Close()
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatal(err)
	}
	for _, statement := range []string{
		`SELECT id ## 1 FROM public.qurio_policy_probe`,
		`SELECT id::public.qurio_policy_domain FROM public.qurio_policy_probe`,
		`SELECT public.qurio_policy_domain '1' FROM public.qurio_policy_probe`,
	} {
		if _, err := manager.Execute(ctx, config.ID, statement, 1, 10); err == nil {
			t.Fatalf("implicit user-code dispatch was accepted: %s", statement)
		}
	}
	for _, statement := range []string{
		`SELECT * FROM public.qurio_policy_domain_table`,
		`SELECT * FROM public.qurio_policy_view`,
		`SELECT * FROM (public.qurio_policy_probe probe JOIN public.qurio_policy_view unsafe_view ON true) grouped`,
		`SELECT * FROM public.qurio_policy_partition_expression`,
		`SELECT * FROM public.qurio_policy_partition_opclass`,
	} {
		if _, err := manager.Execute(ctx, config.ID, statement, 1, 10); !errors.Is(err, ErrUnsafeDatabaseObject) {
			t.Fatalf("unsafe relation %q error = %v", statement, err)
		}
	}
	if _, err := manager.Execute(ctx, config.ID,
		`SELECT * FROM (public.qurio_policy_probe probe JOIN private.qurio_policy_hidden hidden ON true) grouped`, 1, 10); !errors.Is(err, ErrSchemaNotAllowed) {
		t.Fatalf("parenthesized joined-table bypassed schema policy: %v", err)
	}
}

func TestPostgresRejectsNonInitdbCatalogOverridesAndBuiltinCasts(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	config := integrationConnection(t)
	config.AllowedSchemas = []string{"public"}
	setup, err := open(config)
	if err != nil {
		t.Skipf("Qurio integration PostgreSQL is not running: %v", err)
	}
	defer setup.Close()
	catalogOverrideCreated := false
	castCreated := false
	castFunctionCreated := false
	defer func() {
		if catalogOverrideCreated {
			_, _ = setup.ExecContext(context.Background(), `DROP FUNCTION pg_catalog.lower(integer)`)
		}
		if castCreated {
			_, _ = setup.ExecContext(context.Background(), `DROP CAST (date AS integer)`)
		}
		if castFunctionCreated {
			_, _ = setup.ExecContext(context.Background(), `DROP FUNCTION public.qurio_date_to_integer(date)`)
		}
	}()

	manager := New(nil)
	defer manager.Close()
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatal(err)
	}

	// pg_catalog is writable by a database superuser. An allowlisted function
	// name must not become trusted merely because a custom overload is placed
	// there; this query has no base relation for relation preflight to discover.
	_, createCatalogErr := setup.ExecContext(ctx, `
		CREATE FUNCTION pg_catalog.lower(integer) RETURNS text
		LANGUAGE sql IMMUTABLE PARALLEL SAFE
		AS 'SELECT ''custom-catalog-overload''::text'`)
	if createCatalogErr != nil {
		t.Logf("database role cannot create a pg_catalog overload; live overload assertion skipped: %v", createCatalogErr)
	} else {
		catalogOverrideCreated = true
		if _, err := manager.Execute(ctx, config.ID, `SELECT lower(42)`, 1, 1); !errors.Is(err, ErrUnsafeDatabaseObject) {
			t.Fatalf("non-initdb pg_catalog overload error = %v", err)
		}
		if _, err := setup.ExecContext(ctx, `DROP FUNCTION pg_catalog.lower(integer)`); err != nil {
			t.Fatalf("remove pg_catalog overload: %v", err)
		}
		catalogOverrideCreated = false
	}

	// Casts have no namespace. A custom cast between two bootstrap types can
	// therefore dispatch a function outside pg_catalog even though both type
	// tokens pass the static built-in-type allowlist.
	if _, err := setup.ExecContext(ctx, `CREATE FUNCTION public.qurio_date_to_integer(date) RETURNS integer LANGUAGE sql IMMUTABLE AS 'SELECT 1'`); err != nil {
		t.Fatalf("prepare custom cast function: %v", err)
	}
	castFunctionCreated = true
	if _, err := setup.ExecContext(ctx, `CREATE CAST (date AS integer) WITH FUNCTION public.qurio_date_to_integer(date) AS ASSIGNMENT`); err != nil {
		t.Fatalf("prepare custom built-in cast: %v", err)
	}
	castCreated = true
	if _, err := manager.Execute(ctx, config.ID, `SELECT CAST(DATE '2026-08-31' AS INTEGER)`, 1, 1); !errors.Is(err, ErrUnsafeDatabaseObject) {
		t.Fatalf("custom cast between built-in types error = %v", err)
	}
}

func TestPostgresRelationGraphDeduplicatesAndStopsAtLimit(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	config := integrationConnection(t)
	config.AllowedSchemas = []string{"public"}
	config.Timeout = 10 * time.Second
	setup, err := open(config)
	if err != nil {
		t.Skipf("Qurio integration PostgreSQL is not running: %v", err)
	}
	defer setup.Close()
	defer func() {
		_, _ = setup.ExecContext(context.Background(), `DROP TABLE IF EXISTS public.qurio_graph_base CASCADE`)
		_, _ = setup.ExecContext(context.Background(), `DROP TABLE IF EXISTS public.qurio_graph_partitioned CASCADE`)
	}()
	for _, statement := range []string{
		`DROP TABLE IF EXISTS public.qurio_graph_base CASCADE`,
		`DROP TABLE IF EXISTS public.qurio_graph_partitioned CASCADE`,
		`CREATE TABLE public.qurio_graph_base(id integer)`,
		`CREATE VIEW public.qurio_graph_v0 AS SELECT id FROM public.qurio_graph_base`,
		`CREATE VIEW public.qurio_graph_v1 AS SELECT id FROM public.qurio_graph_base`,
	} {
		if _, err := setup.ExecContext(ctx, statement); err != nil {
			t.Fatalf("prepare deduplicated graph: %v", err)
		}
	}
	// Every new view points to the previous two. Path-based recursion grows
	// exponentially even though the graph contains only a few distinct OIDs.
	for index := 2; index <= 12; index++ {
		statement := fmt.Sprintf(`CREATE VIEW public.qurio_graph_v%d AS
			SELECT previous.id FROM public.qurio_graph_v%d previous
			JOIN public.qurio_graph_v%d earlier USING (id)`, index, index-1, index-2)
		if _, err := setup.ExecContext(ctx, statement); err != nil {
			t.Fatalf("prepare view %d: %v", index, err)
		}
	}

	manager := New(nil)
	defer manager.Close()
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatal(err)
	}
	if _, err := manager.Execute(ctx, config.ID, `SELECT id FROM public.qurio_graph_v12`, 1, 1); err != nil {
		t.Fatalf("deduplicated relation graph was rejected: %v", err)
	}

	if _, err := setup.ExecContext(ctx, `CREATE TABLE public.qurio_graph_partitioned(id integer) PARTITION BY RANGE (id)`); err != nil {
		t.Fatalf("prepare partition root: %v", err)
	}
	for index := 0; index < postgresRelationObjectLimit; index++ {
		statement := fmt.Sprintf(`CREATE TABLE public.qurio_graph_partition_%03d
			PARTITION OF public.qurio_graph_partitioned FOR VALUES FROM (%d) TO (%d)`, index, index, index+1)
		if _, err := setup.ExecContext(ctx, statement); err != nil {
			t.Fatalf("prepare partition %d: %v", index, err)
		}
	}
	if _, err := manager.Execute(ctx, config.ID, `SELECT id FROM public.qurio_graph_partitioned`, 1, 1); !errors.Is(err, ErrUnsafeDatabaseObject) {
		t.Fatalf("257-object relation graph error = %v", err)
	}
}

func TestPostgresPreflightStatementTimeoutRestoresConfiguredLimit(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	config := integrationConnection(t)
	config.Timeout = 12 * time.Second
	db, err := open(config)
	if err != nil {
		t.Skipf("Qurio integration PostgreSQL is not running: %v", err)
	}
	defer db.Close()
	tx, err := db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelRepeatableRead, ReadOnly: true})
	if err != nil {
		t.Fatal(err)
	}
	defer tx.Rollback()
	if err := setPostgresLocalStatementTimeout(ctx, tx, postgresObjectPreflightTimeout(config.Timeout)); err != nil {
		t.Fatal(err)
	}
	var preflight string
	if err := tx.QueryRowContext(ctx, `SHOW statement_timeout`).Scan(&preflight); err != nil {
		t.Fatal(err)
	}
	if preflight != "5s" {
		t.Fatalf("preflight statement_timeout = %q", preflight)
	}
	if err := setPostgresLocalStatementTimeout(ctx, tx, config.Timeout); err != nil {
		t.Fatal(err)
	}
	var restored string
	if err := tx.QueryRowContext(ctx, `SHOW statement_timeout`).Scan(&restored); err != nil {
		t.Fatal(err)
	}
	if restored != "12s" {
		t.Fatalf("restored statement_timeout = %q", restored)
	}
}

func integrationConnection(t *testing.T) Connection {
	t.Helper()
	dsn := os.Getenv("POSTGRES_DSN")
	if dsn == "" {
		dsn = "postgres://qurio:qurio-test@127.0.0.1:55432/qurio?sslmode=disable"
	}
	parsed, err := url.Parse(dsn)
	if err != nil {
		t.Fatalf("parse integration DSN: %v", err)
	}
	password, _ := parsed.User.Password()
	port := 5432
	if parsed.Port() != "" {
		port, err = strconv.Atoi(parsed.Port())
		if err != nil {
			t.Fatalf("parse integration port: %v", err)
		}
	}
	sslMode := parsed.Query().Get("sslmode")
	if sslMode == "" {
		sslMode = "disable"
	}
	return Connection{ID: "meta-test", Name: "Integration PostgreSQL", Dialect: Postgres, Host: parsed.Hostname(), Port: port, Username: parsed.User.Username(), Password: password, Database: strings.TrimPrefix(parsed.Path, "/"), Options: map[string]string{"sslmode": sslMode}, Timeout: 2 * time.Second}
}
