func TestSchemaQueriesApplyAllowedSchemasBeforeCatalogLimit(t *testing.T) {
	columns, foreignKeys, args := postgresSchemaQueries(800, []string{"ZZ_APP", "analytics"})
	if !strings.Contains(columns, "namespace.nspname IN ($1,$2)") || strings.Index(columns, "namespace.nspname IN") > strings.Index(columns, "LIMIT 800") {
		t.Fatalf("PostgreSQL column allowlist is not before limit: %s", columns)
	}
	if !strings.Contains(foreignKeys, "reference_namespace.nspname IN ($1,$2)") || len(args) != 2 || args[0] != "ZZ_APP" {
		t.Fatalf("PostgreSQL FK allowlist/args mismatch: query=%s args=%v", foreignKeys, args)
	}
	columns, foreignKeys, args = oracleSchemaQueries(5000, []string{"app", "FINANCE"})
	if !strings.Contains(columns, "UPPER(c.owner) IN (:allowed_schema_0,:allowed_schema_1)") || strings.Index(columns, "UPPER(c.owner) IN") > strings.Index(columns, "FETCH FIRST 5000") {
		t.Fatalf("Oracle column allowlist is not before limit: %s", columns)
	}
	firstSchema, firstSchemaOK := args[0].(sql.NamedArg)
	if !strings.Contains(foreignKeys, "UPPER(pk.owner) IN (:allowed_schema_0,:allowed_schema_1)") || len(args) != 2 || !firstSchemaOK || firstSchema.Name != "allowed_schema_0" || firstSchema.Value != "APP" {
		t.Fatalf("Oracle FK allowlist/args mismatch: query=%s args=%v", foreignKeys, args)
	}
}

