	columns, foreignKeys, args := postgresTargetedSchemaQueries(900, []string{"public", "analytics"}, targets)
	if !strings.Contains(columns, "namespace.nspname IN ($1,$2)") || !strings.Contains(columns, "relation.relname=$4") || strings.Index(columns, "relation.relname") > strings.Index(columns, "LIMIT 900") {
		t.Fatalf("PostgreSQL targeted column predicate is missing or post-limit: %s", columns)
	}
	if !strings.Contains(foreignKeys, "reference_relation.relname") || len(args) != 6 || args[2] != "analytics" || args[5] != "customers" {
		t.Fatalf("PostgreSQL targeted FK bindings mismatch: query=%s args=%v", foreignKeys, args)
	}
	columns, foreignKeys, args = oracleTargetedSchemaQueries(700, []string{"APP"}, targets)
	if !strings.Contains(columns, "UPPER(c.owner) IN (:allowed_schema_0)") || !strings.Contains(columns, "UPPER(c.table_name)=:target_table_0") || strings.Index(columns, "UPPER(c.table_name)") > strings.Index(columns, "FETCH FIRST 700") {
		t.Fatalf("Oracle targeted column predicate is missing or post-limit: %s", columns)
	}
	firstTargetSchema, firstTargetSchemaOK := args[1].(sql.NamedArg)
	secondTargetTable, secondTargetTableOK := args[4].(sql.NamedArg)
	if !strings.Contains(foreignKeys, "UPPER(pkc.table_name)=:target_table_1") || len(args) != 5 || !firstTargetSchemaOK || firstTargetSchema.Name != "target_schema_0" || firstTargetSchema.Value != "ANALYTICS" || !secondTargetTableOK || secondTargetTable.Name != "target_table_1" || secondTargetTable.Value != "CUSTOMERS" {
		t.Fatalf("Oracle targeted FK bindings mismatch: query=%s args=%v", foreignKeys, args)
	}
}

