// TestOracleLiveConnectionSchemaValidationAndExecution is opt-in outside the
// release workflow. It exercises the exact pure-Go driver and Manager path
// used by an offline Qurio image when the QURIO_TEST_ORACLE_* variables point
// at a disposable Oracle instance.
func TestOracleLiveConnectionSchemaValidationAndExecution(t *testing.T) {
	host := strings.TrimSpace(os.Getenv("QURIO_TEST_ORACLE_HOST"))
	username := strings.TrimSpace(os.Getenv("QURIO_TEST_ORACLE_USERNAME"))
	password := os.Getenv("QURIO_TEST_ORACLE_PASSWORD")
	service := strings.TrimSpace(os.Getenv("QURIO_TEST_ORACLE_SERVICE"))
	if host == "" || username == "" || password == "" || service == "" {
		t.Skip("QURIO_TEST_ORACLE_HOST, _USERNAME, _PASSWORD and _SERVICE are required")
	}
	port := 1521
	if raw := strings.TrimSpace(os.Getenv("QURIO_TEST_ORACLE_PORT")); raw != "" {
		parsed, err := strconv.Atoi(raw)
		if err != nil || parsed < 1 || parsed > 65535 {
			t.Fatalf("invalid QURIO_TEST_ORACLE_PORT %q", raw)
		}
		port = parsed
	}
	schema := strings.ToUpper(username)
	if configured := strings.TrimSpace(os.Getenv("QURIO_TEST_ORACLE_SCHEMA")); configured != "" {
		schema = strings.ToUpper(configured)
	}

	config := Connection{
		ID:             "oracle-live-integration",
		Name:           "Oracle live integration",
		Dialect:        Oracle,
		Host:           host,
		Port:           port,
		Username:       username,
		Password:       password,
		Database:       service,
		AllowedSchemas: []string{schema},
		MaxRows:        100,
		Timeout:        90 * time.Second,
	}

	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()
	driver, dsn, err := dataSource(config)
	if err != nil {
		t.Fatalf("build Oracle data source: %v", err)
	}
	seed, err := sql.Open(driver, dsn)
	if err != nil {
		t.Fatalf("open Oracle seed connection: %v", err)
	}
	defer seed.Close()
	if err := seed.PingContext(ctx); err != nil {
		t.Fatalf("ping Oracle seed connection: %v", err)
	}

	suffix := fmt.Sprintf("%08X", uint32(time.Now().UnixNano()))
	parent := "QURIO_IT_P_" + suffix
	child := "QURIO_IT_C_" + suffix
	defer func() { _, _ = seed.ExecContext(context.Background(), "DROP TABLE "+parent+" PURGE") }()
	defer func() { _, _ = seed.ExecContext(context.Background(), "DROP TABLE "+child+" PURGE") }()
	if _, err := seed.ExecContext(ctx, "CREATE TABLE "+parent+" (ID NUMBER PRIMARY KEY, NAME VARCHAR2(80) NOT NULL)"); err != nil {
		t.Fatalf("create Oracle parent table: %v", err)
	}
	if _, err := seed.ExecContext(ctx, "CREATE TABLE "+child+" (ID NUMBER PRIMARY KEY, PARENT_ID NUMBER NOT NULL REFERENCES "+parent+"(ID), LABEL VARCHAR2(80))"); err != nil {
		t.Fatalf("create Oracle child table: %v", err)
	}
	for _, statement := range []string{
		"INSERT INTO " + parent + " (ID,NAME) VALUES (1,'Finance')",
		"INSERT INTO " + parent + " (ID,NAME) VALUES (2,'Sales')",
		"INSERT INTO " + child + " (ID,PARENT_ID,LABEL) VALUES (10,1,'Budget')",
		"INSERT INTO " + child + " (ID,PARENT_ID,LABEL) VALUES (20,2,'Pipeline')",
	} {
		if _, err := seed.ExecContext(ctx, statement); err != nil {
			t.Fatalf("seed Oracle integration table: %v", err)
		}
	}

	manager := New(nil)
	defer manager.Close()
	if err := manager.Test(ctx, config); err != nil {
		t.Fatalf("test Oracle Manager connection: %v", err)
	}
	if _, err := manager.Upsert(ctx, config); err != nil {
		t.Fatalf("register Oracle Manager connection: %v", err)
	}

	snapshot, err := manager.ExploreSchemaTargets(ctx, config.ID, []SchemaTarget{
		{Schema: schema, Table: parent},
		{Schema: schema, Table: child},
	}, 100)
	if err != nil {
		columnsQuery, foreignKeysQuery, args := oracleTargetedSchemaQueries(100, config.AllowedSchemas, []SchemaTarget{
			{Schema: schema, Table: parent},
			{Schema: schema, Table: child},
		})
		for label, query := range map[string]string{"columns": columnsQuery, "foreign keys": foreignKeysQuery} {
			rows, queryErr := seed.QueryContext(ctx, query, args...)
			if queryErr != nil {
				t.Fatalf("explore Oracle schema targets: %v; raw %s query: %v", err, label, queryErr)
			}
			_ = rows.Close()
		}
		t.Fatalf("explore Oracle schema targets: %v", err)
	}
	if snapshot.Truncated || len(snapshot.Tables) != 2 {
		t.Fatalf("unexpected Oracle schema snapshot: %#v", snapshot)
	}
	primaryKeys := 0
	for _, table := range snapshot.Tables {
		for _, column := range table.Columns {
			if column.PrimaryKey {
				primaryKeys++
			}
		}
	}
	if primaryKeys != 2 || len(snapshot.ForeignKeys) != 1 {
		t.Fatalf("expected two primary keys and one foreign key, got pk=%d fk=%#v", primaryKeys, snapshot.ForeignKeys)
	}

	query := fmt.Sprintf("SELECT c.ID, p.NAME, c.LABEL FROM %s.%s c JOIN %s.%s p ON p.ID=c.PARENT_ID ORDER BY c.ID", schema, child, schema, parent)
	validation, err := manager.Validate(ctx, config.ID, query)
	if err != nil || !validation.Valid || validation.Strategy != "prepare" {
		t.Fatalf("validate Oracle query: validation=%#v err=%v", validation, err)
	}
	result, err := manager.Execute(ctx, config.ID, query, 1, 20)
	if err != nil {
		t.Fatalf("execute Oracle query: %v", err)
	}
	if result.RowCount != 2 || len(result.Rows) != 2 || fmt.Sprint(result.Rows[0][1]) != "Finance" {
		t.Fatalf("unexpected Oracle execution result: %#v", result)
	}
}
