func TestResolveRowLimitAppliesProfileMaximum(t *testing.T) {
	if got := configuredMaxRows(Connection{}); got != 10_000 {
		t.Fatalf("legacy/default profile maximum = %d, want 10000", got)
	}
	tests := []struct {
		name      string
		requested int
		maximum   int
		want      int
		wantErr   error
	}{
		{name: "default below policy", requested: 0, maximum: 500, want: 200},
		{name: "default capped by policy", requested: 0, maximum: 50, want: 50},
		{name: "explicit within policy", requested: 25, maximum: 50, want: 25},
		{name: "explicit exceeds policy", requested: 51, maximum: 50, wantErr: ErrRowLimitExceeded},
		{name: "profile upper boundary", requested: 100_000, maximum: 100_000, want: 100_000},
		{name: "above profile upper boundary", requested: 100_001, maximum: 100_000, wantErr: ErrRowLimitExceeded},
		{name: "invalid negative", requested: -1, maximum: 50, wantErr: errors.New("invalid")},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			got, err := resolveRowLimit(test.requested, test.maximum)
			if test.wantErr == ErrRowLimitExceeded && !errors.Is(err, ErrRowLimitExceeded) {
				t.Fatalf("error = %v, want ErrRowLimitExceeded", err)
			}
			if test.wantErr != nil && err == nil {
				t.Fatal("expected an error")
			}
			if test.wantErr == nil && (err != nil || got != test.want) {
				t.Fatalf("resolveRowLimit() = %d, %v; want %d", got, err, test.want)
			}
		})
	}
}

