func TestEnforceSchemaPolicy(t *testing.T) {
	postgres := Connection{Dialect: Postgres, AllowedSchemas: []string{"public", "CaseSensitive"}}
	allowed := []string{
		`SELECT item.id FROM public.items item WHERE item.id = 1`,
		`SELECT * FROM "CaseSensitive".items`,
		`SELECT extract(epoch FROM created_at), private.label FROM public.items private`,
		`SELECT 'FROM private.items' AS value /* JOIN private.audit */`,
		`SELECT $$FROM private.items$$ AS value`,
		`WITH recent(id) AS (SELECT id FROM public.items), materialized AS NOT MATERIALIZED (SELECT id FROM recent) SELECT * FROM materialized`,
		`WITH materialized AS MATERIALIZED (SELECT id FROM public.items) SELECT * FROM materialized`,
		`WITH RECURSIVE nodes(id) AS (SELECT id FROM public.items UNION ALL SELECT node.id FROM nodes node) SELECT * FROM nodes`,
	}
	for _, statement := range allowed {
		if err := enforceSchemaPolicy(postgres, statement); err != nil {
			t.Errorf("allowed statement rejected: %q: %v", statement, err)
		}
	}
	rejected := []string{
		`SELECT * FROM private.items`,
		`SELECT * FROM public.items item JOIN private.audit audit ON true`,
		`SELECT * FROM public.items item, private.audit audit`,
		`SELECT * FROM (SELECT * FROM private.audit) audit`,
		`SELECT * FROM ONLY (private.audit)`,
		`WITH source AS (TABLE private.audit) SELECT * FROM source`,
		`SELECT * FROM "public".items JOIN "Private".audit ON true`,
		`SELECT * FROM (public.items item JOIN private.audit audit ON audit.id=item.id) grouped`,
		`SELECT * FROM ((public.items item JOIN private.audit audit ON audit.id=item.id)) grouped`,
	}
	for _, statement := range []string{
		`SELECT * FROM (public.items item JOIN public.audit audit ON audit.id=item.id) grouped`,
		`SELECT * FROM ((public.items item JOIN public.audit audit ON audit.id=item.id)) grouped`,
	} {
		if err := enforceSchemaPolicy(postgres, statement); err != nil {
			t.Errorf("allowed parenthesized joined-table rejected: %q: %v", statement, err)
		}
	}
	for _, statement := range []string{
		`SELECT * FROM items`,
		`SELECT * FROM items item, public.audit audit`,
		`SELECT * FROM (WITH pg_class AS (SELECT * FROM public.items) SELECT * FROM pg_class) nested JOIN pg_class outer_catalog ON true`,
		`SELECT * FROM (SELECT 1 FROM public.items WINDOW pg_class AS ()) nested JOIN pg_class outer_catalog ON true`,
		`WITH pg_class AS (SELECT * FROM pg_class) SELECT * FROM pg_class`,
	} {
		if err := enforceSchemaPolicy(postgres, statement); !errors.Is(err, ErrUnqualifiedRelation) {
			t.Errorf("unqualified relation was not rejected: %q: %v", statement, err)
		}
	}
	for _, statement := range rejected {
		if err := enforceSchemaPolicy(postgres, statement); !errors.Is(err, ErrSchemaNotAllowed) {
			t.Errorf("statement was not rejected: %q: %v", statement, err)
		}
	}
	// PostgreSQL would keep the close parenthesis inside the outer comment.
	// A flat lexer that stopped at the inner terminator could drop SELECT depth
	// and miss the actual private relation in the CTE.
	nestedComment := `WITH hidden AS (SELECT 1 /* outer /* inner */ ) */ FROM private.audit) SELECT * FROM hidden`
	if err := enforceSchemaPolicy(postgres, nestedComment); !errors.Is(err, ErrUnsafeStatement) {
		t.Fatalf("nested-comment relation ambiguity was not rejected: %v", err)
	}

	oracle := Connection{Dialect: Oracle, AllowedSchemas: []string{"REPORTING"}}
	if err := enforceSchemaPolicy(oracle, `SELECT * FROM reporting.sales`); err != nil {
		t.Fatalf("Oracle unquoted identifiers must be case-insensitive: %v", err)
	}
	if err := enforceSchemaPolicy(oracle, `WITH sales AS (SELECT * FROM reporting.sales) SELECT * FROM sales`); err != nil {
		t.Fatalf("Oracle qualified CTE source was rejected: %v", err)
	}
	if err := enforceSchemaPolicy(oracle, `SELECT 1 FROM dual`); err != nil {
		t.Fatalf("Oracle DUAL grammar relation was rejected: %v", err)
	}
	for _, statement := range []string{
		`SELECT * FROM sales`,
		`SELECT * FROM reporting.sales approved JOIN secret.audit hidden ON 1=1`,
		`SELECT * FROM (SELECT * FROM secret.audit) hidden`,
	} {
		if err := enforceSchemaPolicy(oracle, statement); err == nil {
			t.Fatalf("Oracle implicit/disallowed relation was accepted: %q", statement)
		}
	}
	if err := enforceSchemaPolicy(oracle, `SELECT * FROM private.sales`); !errors.Is(err, ErrSchemaNotAllowed) {
		t.Fatalf("Oracle disallowed schema error = %v", err)
	}
	if err := enforceSchemaPolicy(oracle, `SELECT * FROM "reporting".sales`); !errors.Is(err, ErrSchemaNotAllowed) {
		t.Fatalf("Oracle quoted schema case bypassed the allowlist: %v", err)
	}
}

func TestAnalyzeExecutionPolicyIsDialectAware(t *testing.T) {
	t.Parallel()
	oracle := Connection{Dialect: Oracle, AllowedSchemas: []string{"REPORTING"}}
	for _, statement := range []string{
		`SELECT * FROM reporting.sales@remote_link`,
		`SELECT side_effect_fn() FROM dual`,
		`SELECT app.abs(amount) FROM reporting.sales`,
		`SELECT sales_sequence.NEXTVAL FROM dual`,
	} {
		analysis, err := analyzeExecutionPolicy(oracle, statement)
		if !errors.Is(err, ErrUnsafeStatement) || analysis.ReadOnly {
			t.Fatalf("Oracle policy accepted %q: analysis=%#v error=%v", statement, analysis, err)
		}
	}
	if analysis, err := analyzeExecutionPolicy(oracle, `SELECT COUNT(*), LOWER(status) FROM reporting.sales GROUP BY LOWER(status)`); err != nil || !analysis.ReadOnly {
		t.Fatalf("Oracle intrinsic query rejected: analysis=%#v error=%v", analysis, err)
	}
	if analysis, err := analyzeExecutionPolicy(oracle, `SELECT COUNT(*) FROM sales`); !errors.Is(err, ErrUnqualifiedRelation) || !analysis.ReadOnly {
		t.Fatalf("Oracle unqualified relation policy result: analysis=%#v error=%v", analysis, err)
	}

	postgres := Connection{Dialect: Postgres, AllowedSchemas: []string{"public"}}
	if analysis, err := analyzeExecutionPolicy(postgres, `SELECT custom_reporting_fn(id) FROM public.events`); !errors.Is(err, ErrUnsafeStatement) || analysis.ReadOnly {
		t.Fatalf("PostgreSQL UDF policy accepted executable code: analysis=%#v error=%v", analysis, err)
	}
	if analysis, err := analyzeExecutionPolicy(postgres, `SELECT COUNT(*), LOWER(status), payload @> '{}'::jsonb FROM public.events GROUP BY status, payload`); err != nil || !analysis.ReadOnly {
		t.Fatalf("PostgreSQL intrinsic query rejected: analysis=%#v error=%v", analysis, err)
	}
}

func TestPostgresSearchPathIsCatalogOnly(t *testing.T) {
	got := postgresSearchPathStatement([]string{"public", `odd"name`})
	want := `SET LOCAL search_path TO pg_catalog`
	if got != want {
		t.Fatalf("search path = %q, want %q", got, want)
	}
}

func TestValidateExecutionPolicy(t *testing.T) {
	valid := Connection{Dialect: Postgres, AllowedSchemas: []string{"public", "Mixed Case"}, MaxRows: 100_000}
	if err := validateExecutionPolicy(valid); err != nil {
		t.Fatal(err)
	}
	invalid := []Connection{
		{Dialect: Postgres, MaxRows: -1},
		{Dialect: Postgres, MaxRows: 100_001},
		{Dialect: Postgres, AllowedSchemas: []string{" public"}},
		{Dialect: Postgres, AllowedSchemas: []string{"public", "public"}},
		{Dialect: Oracle, AllowedSchemas: []string{"reporting", "REPORTING"}},
		{Dialect: Postgres, AllowedSchemas: []string{strings.Repeat("가", 129)}},
	}
	for _, config := range invalid {
		if err := validateExecutionPolicy(config); !errors.Is(err, ErrInvalidConnection) {
			t.Errorf("config %#v error = %v", config, err)
		}
	}
}
# Qurio architecture

## Design goals

Qurio packages the legacy platform's user and administrator capabilities into a
single auditable service. The modular-monolith boundary removes the operational
dependency on 18 FastAPI services, Redis, Celery, Qdrant, NebulaGraph, Nginx,
and two separate frontend containers while preserving domain separation in the
code and API.

```mermaid
flowchart LR
  Browser[React SPA] --> HTTP[Go HTTP API]
  Agent[MCP or REST client] --> HTTP
  HTTP --> Auth[Auth, OIDC, RBAC]
  HTTP --> Workbench[NL2SQL and code workbench]
  HTTP --> Admin[Governance console]
  HTTP --> MCP[MCP client and server]
  Workbench --> AI[AI provider adapter]
  Workbench --> Catalog[Metadata, topology, RAG]
  Auth & Workbench & Admin & MCP & Catalog --> PG[(PostgreSQL)]
  MCP --> RemoteMCP[Remote MCP servers]
  AI --> RemoteAI[OpenAI-compatible or local AI]
  Workbench --> BusinessDB[Approved business databases]
```

## Frontend decision

Qurio uses Mantine with React and TypeScript. The legacy blue/orange identity,
neutral surfaces, thin borders, and rounded cards are retained, but the base
font is 16px, secondary text never drops below 14px, focus rings are visible,
and dense tables have mobile card or horizontal-scroll alternatives. Mantine's
theme and Styles API allow the legacy look to be expressed without runtime
stylesheets or CDN assets.

The URL is the source of truth for the active page. Navigation expansion,
sidebar width, scroll position, color mode, and font scale are supplementary
local preferences. A browser refresh therefore reconstructs the exact menu and
workspace from the route instead of falling back to a dashboard.

## Backend modules

| Module | Responsibility |
|---|---|
| platform | Configuration, database, migrations, encryption, audit, jobs |
| identity | Local authentication, Keycloak OIDC, sessions, users, teams, RBAC |
| catalog | Dictionaries, logical/physical models, embedding collections, schema inspection, versions |
| topology | Join relationships, indexes, SQL-derived guides, graph projection |
| intelligence | Provider profiles, prompts, streaming, token budgets, RAG |
| agent | Durable metadata/live-schema NL2SQL runs, repair, approval resume, feedback |
| workbench | SQL projects, rooms, messages, validation, execution, exports |
| evaluation | Datasets, metrics, evaluation runs, summaries, regressions |
| code | Projects, file workspace, Git operations, code assistant |
| integration | Database connections, multi-server MCP client, Qurio MCP server |
| governance | Approval policy, review events, key policy, backup, analytics |

## Environment and settings

The process consumes only `POSTGRES_DSN`, `BOOTSTRAP_ADMIN`,
`BOOTSTRAP_ADMIN_PASSWORD`, and `ENCRYPTION_KEY`. These are bootstrap roots of
trust and cannot be overridden through the UI. All operational configuration is
stored as typed settings with validation, audit history, optimistic revision,
and secret references.

OIDC configuration requires an issuer URL, client ID, client secret, and optional
claim mappings. Discovery, authorization/token/JWKS endpoints, PKCE, redirect
URI, state, nonce, JIT provisioning, and role mapping are automatic.
An unrecognized OIDC subject may be linked to an existing local identity only
when the provider explicitly asserts `email_verified=true`; a missing claim is
not treated as proof. Existing issuer/subject links and non-colliding JIT users
remain subject-based.

## Cryptography and keys

The environment master key encrypts setting and credential envelopes with
AES-256-GCM. Secret records include an envelope key version, random nonce,
authenticated context, and ciphertext. The envelope format can identify future
key versions, but the current service loads only the configured v1 master key and does not
ship an in-place master-key migration job. Replacing `ENCRYPTION_KEY` on an
existing database therefore makes encrypted values unreadable.

Provider, MCP, OIDC, database, and repository credentials can create new secret
record versions without exposing their plaintext. This record-level credential
rotation is separate from the unsupported environment master-key migration.

Personal API keys are generated with cryptographic randomness, shown once, and
stored only as SHA-256 hashes with a visible prefix. Each key has independently
editable scopes, expiry, rate policy, last-use time, and rotation lineage. Role
permissions and key scopes are intersected at request time. Every change and
use is audited. RPM, TPM, and concurrent-request accounting follows the full
rotation lineage, so replacing a credential cannot reset a live quota window;
the outgoing request lease remains releasable after the old credential is
deactivated.

## Streaming and token budget

AI requests always stream from provider to browser, REST clients, and MCP
adapters. The administrator screen exposes this as a read-only runtime policy
rather than a switch whose value could diverge from the execution path.
The provider profile records API style, context window, maximum output, timeout,
sampling parameters, and health state. Qurio accepts configured limits through
262,144 tokens, but clamps each request to the selected model profile and the
remaining context budget. Usage stores input, cached, reasoning, and output
tokens separately when provided.

OpenAI-compatible Responses and Chat Completions adapters normalize public
deltas into Qurio events: `status`, `tool_call`, `text_delta`, `usage`, `done`,
and `error`. Provider reasoning is counted only for aggregate usage accounting;
it is never retained as completion text or sent to browser, REST, or MCP clients.
The request is cancelled when the browser disconnects.

## MCP

Qurio is both an MCP client and server. Administrators can register multiple
Streamable HTTP or stdio servers, attach encrypted headers, discover tools,
enable tools, constrain schemas, set timeouts/rate limits, and bind tool access
to roles, teams, and keys. Tool calls display consent and approval requirements
and produce an audit event.

Every enabled policy that applies to the caller, server, and tool is combined;
there is no first-match override. A deny wins, schema constraints are
intersected, consent or approval requirements are ORed, and the strictest rate
and timeout limits win. The principal, API-key scope, current tool definition,
policy set, and encrypted-header secret version are resolved again immediately
before dispatch, so revocation, rotation, and policy edits take effect without a
service restart.

The client registry accepts current Streamable HTTP and administrator-
allowlisted STDIO transports. The obsolete standalone MCP SSE transport is not
accepted; rows left by an older installation are disabled by migration and must
be recreated as Streamable HTTP. HTTP headers and STDIO environment maps are
write-only encrypted secrets with explicit keep, rotate, and delete actions.

The Qurio MCP endpoint exposes governance-aware tools for catalog search, SQL
generation, target validation, approval submission/status, safe execution,
evaluation, metadata queries, and full agentic NL2SQL. `qurio_agent_nl2sql` and
`qurio_agent_resume` call the same protocol-neutral orchestrator as the browser's
`/api/v1/agent/runs/stream` and `/resume` routes. REST and MCP therefore persist
the same steps and cannot bypass runtime policy through a different protocol.

## Agentic NL2SQL lifecycle

```mermaid
flowchart LR
  Q[Question] --> C[Governed catalog search]
  C --> S[Live target schema, PK and FK]
  S --> G[Streaming SQL generation]
  G --> V[Read-only and target DB validation]
  V -->|diagnostic, bounded retry| C
  V --> A{Matching review workflow?}
  A -->|yes| W[Persist pending approval]
  W -->|approved, same SQL digest| X[Governed execution]
  A -->|no, bypass recorded| X
  X --> E[Result explanation and feedback]
  C & S & G & V & W & X & E --> P[(Agent run, steps, messages and usage)]
```

Catalog evidence is untrusted model input and bounded to 512 KiB. The generated
statement must name a live table and pass the lexical safety gate. PostgreSQL is
validated with `EXPLAIN (FORMAT JSON)` in a read-only transaction; Oracle uses
server-side prepare because `EXPLAIN PLAN` writes to `PLAN_TABLE`. No validation
step samples business rows. A failed diagnostic can trigger at most the
administrator-configured repair count, and insufficient evidence fails closed.
After governed execution, the optional AI explanation receives only bounded
column shape, page-row count, pagination, and timing metadata. Target-database
row values are never sent to that explanation provider, regardless of aliases.
Oracle analysis rejects database-link references, sequence pseudocolumns, and
lexically identifiable parenthesized function dispatch outside a conservative
intrinsic allowlist; the same policy runs at validation and final bounded-query
construction. It remains a defense-in-depth lexer—particularly because Oracle
no-argument functions can resemble columns—so the target Oracle identity is
independently limited to `SELECT` on approved objects and has no stored-code,
database-link, file, or network privileges.

## Optional review workflow

The workflow is feature-configured, not hard-coded. When disabled, review states
and actions are omitted from API representations and UI navigation. When enabled,
matching operations transition through `DRAFT -> PENDING_REVIEW -> APPROVED` or
`REJECTED`; team managers or explicitly permitted reviewers act according to the
configured quorum and segregation-of-duties rules.

## Database compatibility

Legacy tables remain in place and are accessed through compatibility adapters.
Qurio writes new platform state to namespaced `qurio_*` tables. Migrations take a
PostgreSQL advisory lock, use a checksum ledger, and contain additive DDL only.
After migration, startup performs a read-only compatibility preflight over every
legacy table used by an endpoint. It checks canonical and historical aliases,
column type families, nullability, required enum labels, primary and unique
keys, and foreign keys. A drift that could make an existing SmartSQL deployment
unsafe keeps readiness closed instead of changing a shared column in place.
See [Legacy compatibility](legacy-compatibility.md).
