func TestCoreSensitiveGETRoutesUseExactCredentialPublicationGuard(t *testing.T) {
	dsn := strings.TrimSpace(os.Getenv("QURIO_TEST_POSTGRES_DSN"))
	if dsn == "" {
		t.Skip("set QURIO_TEST_POSTGRES_DSN to a disposable PostgreSQL database")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Close()
	if err := store.RunMigrations(ctx, pool, migrations.FS, "."); err != nil {
		t.Fatal(err)
	}
	keyring, err := cryptox.New([]byte("0123456789abcdef0123456789abcdef"))
	if err != nil {
		t.Fatal(err)
	}
	repository := store.New(pool, keyring)
	nonce := fmt.Sprintf("%x", time.Now().UnixNano())
	var userID int64
	if err := pool.QueryRow(ctx, `INSERT INTO users(name,role,is_active) VALUES($1,'ADMIN',TRUE) RETURNING id`, "core-read-"+nonce).Scan(&userID); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _, _ = pool.Exec(context.Background(), `DELETE FROM users WHERE id=$1`, userID) })
	if _, err := pool.Exec(ctx, `INSERT INTO authentications(email,user_id,provider,must_change_password) VALUES($1,$2,'local',FALSE)`, "core-read-"+nonce+"@test.invalid", userID); err != nil {
		t.Fatal(err)
	}
	if _, err := pool.Exec(ctx, `INSERT INTO qurio_user_roles(user_id,role_code,scope_type,scope_id,assigned_by) VALUES($1,'ADMIN','GLOBAL','*',$1)`, userID); err != nil {
		t.Fatal(err)
	}
	tokens, err := repository.CreateSession(ctx, userID, time.Hour, "", "core-read-test")
	if err != nil {
		t.Fatal(err)
	}
	principal, err := repository.SessionByToken(ctx, tokens.SessionToken)
	if err != nil {
		t.Fatal(err)
	}
	principal.TokenHash = ""
	server, err := New(Options{Store: repository})
	if err != nil {
		t.Fatal(err)
	}
	server.readGuard, err = authzread.New(authzread.Options{
		Pool: pool,
		Principal: func(*http.Request) (store.Session, bool) {
			return principal, true
		},
		WriteProblem: func(w http.ResponseWriter, r *http.Request, status int, code, message string) {
			writeError(w, r, status, code, message)
		},
	})
